-- ============================================================
-- 001_core_tables.sql
-- 核心表结构初始化（PostgreSQL 版，幂等：IF NOT EXISTS）
--
-- 沿革：本文件原为 MySQL 语法（移植早期遗留），从未在生产
-- PostgreSQL 执行、未登记 sys_schema_migration。2026-11-22
-- 用户裁决方案 1：改写为 PostgreSQL 语法、正式补跑补登记，
-- 使迁移序列 001–046 完整。改写口径（随附报告
-- push-queue/migration-001-002-pg/REPORT.md）：
-- - 类型映射：INT→INT、BIGINT→BIGINT、TINYINT→SMALLINT
--   （与 003 起的仓库迁移口径一致）、VARCHAR 长度不变、
--   DECIMAL→NUMERIC、TEXT 不变。两文件均无 UNSIGNED 与
--   DATETIME 列（时间均为 epoch INT/BIGINT），无对应映射。
-- - AUTO_INCREMENT → GENERATED BY DEFAULT AS IDENTITY。
-- - 内联 KEY/UNIQUE KEY 改为独立 CREATE [UNIQUE] INDEX
--   IF NOT EXISTS 语句，索引名沿用原名（生产探针确认未被
--   任何既有索引占用）。
-- - 列/表 COMMENT 转为文件内注释（不落库，避免对既有库
--   产生描述信息变更）；ENGINE/CHARSET/COLLATE 子句删除。
-- - 原文注释掉的 _tig_migrations 占位不再保留：现行登记表
--   为 sys_schema_migration（027 号迁移建立）。
-- 现状（2026-11-22 生产只读探针对账）：admin_login_log 与
-- paylog_rust 两表在生产均不存在、全仓代码零引用，补跑将
-- 真实新建两张空表（无数据影响，非 no-op，见报告发现项
-- F1/F2）；生产支付流水实际在 paylog 表，与 paylog_rust
-- 无关。本文件全部语句可重复执行。
-- ============================================================

-- ------------------------------------------------------------
-- 后台登录日志（原 Java AdminLog 的轻量替代，可选）
-- success 语义：1 成功 0 失败（原文 TINYINT NOT NULL DEFAULT 1）
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS admin_login_log (
    log_id      BIGINT GENERATED BY DEFAULT AS IDENTITY,
    admin_id    INT          NOT NULL,
    username    VARCHAR(64)  NOT NULL DEFAULT '',
    login_ip    VARCHAR(64)  NOT NULL DEFAULT '',
    login_time  BIGINT       NOT NULL DEFAULT 0,
    success     SMALLINT     NOT NULL DEFAULT 1,
    fail_reason VARCHAR(255) NOT NULL DEFAULT '',
    PRIMARY KEY (log_id)
);
CREATE INDEX IF NOT EXISTS idx_admin_id ON admin_login_log (admin_id);
CREATE INDEX IF NOT EXISTS idx_login_time ON admin_login_log (login_time);

-- ------------------------------------------------------------
-- 支付流水（对齐原 finance.Paylog，供支付回调幂等使用）
-- status 语义：1 成功 2 失败 3 退款
-- notify_raw：渠道回调原始报文
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS paylog_rust (
    paylog_id    BIGINT GENERATED BY DEFAULT AS IDENTITY,
    order_id     INT            NOT NULL DEFAULT 0,
    order_sn     VARCHAR(32)    NOT NULL DEFAULT '',
    user_id      INT            NOT NULL DEFAULT 0,
    pay_type_id  INT            NOT NULL DEFAULT 0,
    trade_no     VARCHAR(64)    NOT NULL DEFAULT '',
    out_trade_no VARCHAR(64)    NOT NULL DEFAULT '',
    paid_amount  NUMERIC(20, 4) NOT NULL DEFAULT 0,
    status       SMALLINT       NOT NULL DEFAULT 1,
    notify_raw   TEXT,
    create_time  BIGINT         NOT NULL DEFAULT 0,
    PRIMARY KEY (paylog_id)
);
CREATE UNIQUE INDEX IF NOT EXISTS uk_out_trade_no ON paylog_rust (out_trade_no);
CREATE INDEX IF NOT EXISTS idx_order_sn ON paylog_rust (order_sn);
CREATE INDEX IF NOT EXISTS idx_create_time ON paylog_rust (create_time);
